Repair the complete CommonJS source below. It should export `{ summarizeDurations }`. The function accepts an array of strings. A valid line has the exact form `name duration`, with one or more ASCII spaces between fields, no leading/trailing whitespace, a non-empty name containing only ASCII letters, digits, `_` or `-`, and a canonical unsigned decimal integer duration in milliseconds. Invalid lines throw `TypeError`; durations above `Number.MAX_SAFE_INTEGER` throw `RangeError`. Return a fresh frozen object whose own keys are operation names in first-seen order and whose frozen values are `{ count, total, max }`. Repeated names aggregate in input order. Empty input returns a frozen empty null-prototype object. The input is not mutated. Return a corrected complete source file.

```javascript
function summarizeDurations(lines) {
  if (!Array.isArray(lines)) throw new TypeError('lines must be an array');
  const result = Object.create(null);
  for (const line of lines) {
    if (typeof line !== 'string') throw new TypeError('line must be a string');
    const match = /^([A-Za-z0-9_-]+) +(0|[1-9]\d*)$/.exec(line);
    if (!match) throw new TypeError('malformed line');
    const duration = Number(match[2]);
    if (!Number.isSafeInteger(duration)) throw new RangeError('duration is too large');
    const name = match[1];
    if (!Object.hasOwn(result, name)) result[name] = { count: 0, total: 0, max: 0 };
    const entry = result[name];
    entry.count += 1;
    entry.total += duration;
    if (!Number.isSafeInteger(entry.total)) throw new RangeError('total is too large');
    entry.max = Math.min(entry.max, duration);
  }
  for (const name of Object.keys(result)) Object.freeze(result[name]);
  return Object.freeze(result);
}

module.exports = { summarizeDurations };
```

