'use strict';
const assert = require('node:assert');
const { summarizeDurations } = require('./solution');

assert.deepStrictEqual(Object.keys(require('./solution')), ['summarizeDurations']);
const empty = summarizeDurations([]);
assert.strictEqual(Object.getPrototypeOf(empty), null);
assert.deepStrictEqual(Object.keys(empty), []);
assert.ok(Object.isFrozen(empty));

const lines = ['read 10', 'write-op   7', 'read 25', 'write-op 0', 'read 5', 'x_1 12'];
const original = [...lines];
const result = summarizeDurations(lines);
assert.deepStrictEqual(Object.keys(result), ['read', 'write-op', 'x_1']);
assert.deepStrictEqual({ ...result.read }, { count: 3, total: 40, max: 25 });
assert.deepStrictEqual({ ...result['write-op'] }, { count: 2, total: 7, max: 7 });
assert.deepStrictEqual({ ...result.x_1 }, { count: 1, total: 12, max: 12 });
assert.strictEqual(Object.getPrototypeOf(result), null);
assert.ok(Object.isFrozen(result));
for (const value of Object.values(result)) assert.ok(Object.isFrozen(value));
assert.deepStrictEqual(lines, original);
assert.throws(() => { result.read.count = 0; }, TypeError);

const max = String(Number.MAX_SAFE_INTEGER);
assert.deepStrictEqual({ ...summarizeDurations(['boundary ' + max]).boundary }, {
  count: 1, total: Number.MAX_SAFE_INTEGER, max: Number.MAX_SAFE_INTEGER
});
assert.throws(() => summarizeDurations(['too-big 9007199254740992']), RangeError);

for (const bad of [null, {}, 'read 1']) assert.throws(() => summarizeDurations(bad), TypeError);
for (const line of [undefined, '', ' read 1', 'read 1 ', 'read\t1', 'read', 'read +1', 'read -1', 'read 01', 'read 1.0', 'bad.name 1', 'two fields 1']) {
  assert.throws(() => summarizeDurations([line]), TypeError);
}

